$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$assetDir=Join-Path $PSScriptRoot 'coral-lang\coral-bytecode\assets'
$maps=@{asphalt='asphalt-diff.jpg';brick='brick-diff.jpg';paving='paving-diff.jpg';wood='wood-diff.jpg';plaster='plaster-diff.jpg';grass='grass-diff.jpg';roof='roof-diff.jpg'}
foreach($name in $maps.Keys){$inputFile=Join-Path (Split-Path $PSScriptRoot) ('assets\'+$maps[$name]);$im=[System.Drawing.Image]::FromFile($inputFile);try{$im.Save((Join-Path $assetDir ($name+'.bmp')),[System.Drawing.Imaging.ImageFormat]::Bmp)}finally{$im.Dispose()}}
foreach($name in @('woman','man')){$inputFile=Get-ChildItem -LiteralPath $assetDir -Filter ($name+'-color.*') | Select-Object -First 1;$im=[System.Drawing.Image]::FromFile($inputFile.FullName);try{$im.Save((Join-Path $assetDir ($name+'.bmp')),[System.Drawing.Imaging.ImageFormat]::Bmp)}finally{$im.Dispose()}}
foreach($pair in @(@('cafe','THE CORNER CAFE'),@('books','ASHFORD BOOKS'),@('market','THE GENERAL STORE'))){$bmp=New-Object System.Drawing.Bitmap(1024,128);$g=[System.Drawing.Graphics]::FromImage($bmp);$g.Clear([System.Drawing.Color]::FromArgb(27,49,40));$g.TextRenderingHint=[System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit;$font=New-Object System.Drawing.Font('Georgia',34,[System.Drawing.FontStyle]::Regular);$brush=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(232,223,203));$pen=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(143,151,124),2);$g.DrawRectangle($pen,8,8,1008,112);$format=New-Object System.Drawing.StringFormat;$format.Alignment=[System.Drawing.StringAlignment]::Center;$format.LineAlignment=[System.Drawing.StringAlignment]::Center;$g.DrawString($pair[1],$font,$brush,[System.Drawing.RectangleF]::new(0,0,1024,128),$format);$bmp.Save((Join-Path $assetDir ($pair[0]+'.bmp')),[System.Drawing.Imaging.ImageFormat]::Bmp);$g.Dispose();$font.Dispose();$brush.Dispose();$pen.Dispose();$format.Dispose();$bmp.Dispose()}
$bmp=New-Object System.Drawing.Bitmap(128,128,[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[System.Drawing.Graphics]::FromImage($bmp);$g.Clear([System.Drawing.Color]::Transparent);$g.SmoothingMode=[System.Drawing.Drawing2D.SmoothingMode]::AntiAlias;$brush=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(255,78,104,49));$g.FillEllipse($brush,22,10,82,105);$pen=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(255,135,146,83),2);$g.DrawLine($pen,62,21,64,118);$bmp.Save((Join-Path $assetDir 'leaf.bmp'),[System.Drawing.Imaging.ImageFormat]::Bmp);$g.Dispose();$brush.Dispose();$pen.Dispose();$bmp.Dispose()
Write-Output 'Native BMP surfaces, character textures, signs and foliage prepared.'
